import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  const group = new ctx.THREE.Group();

  // Load texture asynchronously; material will be updated when ready
  const material = new MeshBasicNodeMaterial();
  const texPromise = ctx.textureLoader.loadTexture(config.imageUrl);
  texPromise.then((tex) => {
    material.map = tex;
    material.needsUpdate = true;
    // store texture for disposal
    material.userData = { texture: tex };
  });

  // Plane geometry (size matches typical UI card)
  const geometry = new ctx.THREE.PlaneGeometry(7, 6);
  const mesh = new ctx.THREE.Mesh(geometry, material);
  group.add(mesh);

  // Render text items via font atlas
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  items.forEach((item) => {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 96,
      color: config?.visualSpec?.colors?.paper ?? '#e8ecf2',
      align: 'center',
    });
    // Slight offset to avoid Z‑fighting
    txt.position.set(0, 0, 0.01);
    group.add(txt);
  });

  // Placeholder for event handlers (none defined)
  group.userData.handlers = {};

  // Cleanup routine
  group.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();

    // Dispose loaded texture if present
    if (material.userData?.texture) {
      material.userData.texture.dispose();
    }

    // Dispose any text objects added to the group
    group.traverse((child) => {
      if (child !== group && child !== mesh) {
        if (child.geometry) child.geometry.dispose();
        if (child.material) child.material.dispose();
      }
    });

    // No GSAP timelines were created, but clear any that might exist
    // (safety in case future extensions add timelines)
    // Note: gsap.globalTimeline.clear() would affect all timelines globally,
    // so we only kill timelines we explicitly created (none here).
  };

  return group;
}
